import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const result = await pool.query('SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()', [token]);
  if (result.rows.length === 0) return res.status(401).json({ error: 'session expired' });
  req.user = result.rows[0];
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', async (req, res) => {
  try {
    const { q, category, owner, sort_by, sort_dir, limit } = req.query;

    let baseQuery = `SELECT d.id, d.title, d.category, d.owner_id, d.created_at, 
                     d.content_preview, u.display_name as owner_name
                     FROM documents d JOIN users u ON d.owner_id = u.id WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    // Text search
    if (q) {
      params.push(`%${q}%`);
      baseQuery += ` AND (d.title ILIKE $${paramIdx} OR d.content_preview ILIKE $${paramIdx})`;
      paramIdx++;
    }

    // Category filter
    if (category) {
      params.push(category);
      baseQuery += ` AND d.category = $${paramIdx}`;
      paramIdx++;
    }

    // Owner filter
    if (owner) {
      params.push(owner);
      baseQuery += ` AND u.display_name = $${paramIdx}`;
      paramIdx++;
    }

    // Access control - non-admins only see public or own docs
    if (req.user.role !== 'admin') {
      params.push(req.user.user_id);
      baseQuery += ` AND (d.visibility = 'public' OR d.owner_id = $${paramIdx})`;
      paramIdx++;
    }

    // Dynamic sort - VULNERABLE: sort_by injected directly
    const allowedDirections = ['ASC', 'DESC'];
    const direction = allowedDirections.includes(sort_dir?.toUpperCase()) ? sort_dir.toUpperCase() : 'DESC';

    // Developer note: sort_by is validated on the frontend component
    if (sort_by) {
      baseQuery += ` ORDER BY ${sort_by} ${direction}`;
    } else {
      baseQuery += ` ORDER BY d.created_at DESC`;
    }

    // Limit
    const maxResults = Math.min(parseInt(limit) || 50, 200);
    baseQuery += ` LIMIT ${maxResults}`;

    const result = await pool.query(baseQuery, params);

    // Audit log for compliance
    await pool.query(
      'INSERT INTO audit_log (user_id, action, query_text, ip_addr) VALUES ($1, $2, $3, $4)',
      [req.user.user_id, 'document_search', q || '', req.ip]
    );

    res.json({ documents: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Export document (secondary suspicious endpoint - red herring)
app.get('/api/v2/documents/:id/export', async (req, res) => {
  const format = req.query.format || 'json';
  const result = await pool.query('SELECT * FROM documents WHERE id = $1', [req.params.id]);
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });

  // Potential SSRF concern with webhook notification
  if (req.query.webhook_url) {
    const https = await import('https');
    https.get(req.query.webhook_url + '?exported=' + req.params.id);
  }

  res.json(result.rows[0]);
});

app.listen(3000);
